/* @lc app=leetcode id=988 lang=kotlin */ class Solution { fun smallestFromLeaf(root: TreeNode?): String = generateSequence(listOf(root!! to ('a' + root.`val`).toString())) { f -> f.flatMap { (n, s) -> listOfNotNull(n.left, n.right).map { it to ('a' + it.`val`) + s } }.takeIf { it.isNotEmpty() } }.flatten().filter { (n, _) -> n.left == null && n.right == null }.minOf { it.second } }